/**
 * HuggingFace 模型商城前端模块
 */
(function() {
'use strict';
var _res=[], _queue=[], _selId=null, _files=[];
function fs(b){if(!b)return'未知';var u=['B','KB','MB','GB'];var i=0,s=b;while(s>=1024&&i<u.length-1){s/=1024;i++;}return s.toFixed(1)+' '+u[i];}
function fd(n){if(!n)return'—';return n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e3?(n/1e3).toFixed(1)+'K':n;}
function toast(m,t){var c=document.getElementById('toastContainer');if(!c)return;var e=document.createElement('div');e.className='toast toast-'+(t||'info');e.textContent=m;c.appendChild(e);setTimeout(function(){e.classList.add('show');},10);setTimeout(function(){e.classList.remove('show');setTimeout(function(){e.remove();},300);},3000);}
async function openM(){try{await window.__TAURI__.core.invoke('open_hf_store_window');await loadS();}catch(e){console.error(e);toast('打开商城失败: '+e,'error');}}
async function loadS(){try{var t=await window.__TAURI__.core.invoke('get_hf_token');var ti=document.getElementById('hfTokenInput');if(ti&&t)ti.value='********';var d=await window.__TAURI__.core.invoke('get_hf_download_dir');var di=document.getElementById('hfDownloadDirInput');if(di)d.value=d;}catch(e){console.error(e);}}
async function search(q){if(!q||!q.trim())return;document.getElementById('hfEmptyState').style.display='none';var ls=document.getElementById('hfLoadingState');ls.removeAttribute('hidden');document.getElementById('hfModelsContainer').innerHTML='';document.getElementById('hfDetailPanel').setAttribute('hidden','');try{var r=await window.__TAURI__.core.invoke('search_hf_models',{query:q.trim(),limit:30});_res=r;renderR(r);}catch(e){console.error(e);document.getElementById('hfModelsContainer').innerHTML='<p style="color:var(--danger);padding:20px;text-align:center;">搜索失败</p>';}finally{ls.setAttribute('hidden','');}}
function renderR(models){var c=document.getElementById('hfModelsContainer');if(!models||!models.length){c.innerHTML='<p style="color:var(--text-3);padding:20px;text-align:center;">未找到相关模型</p>';return;}
var html='';for(var i=0;i<models.length;i++){var m=models[i];var tags='';for(var j=0;j<m.tags.length&&j<4;j++){tags+='<span class="hf-model-tag">'+m.tags[j]+'</span>';}
html+='<div class="hf-model-card"><div class="hf-model-card-header"><div class="hf-model-id">'+m.id+'</div></div><div class="hf-model-stats"><span>⬇ '+fd(m.downloads)+'</span><span>♥ '+fd(m.likes)+'</span><span>'+m.model_type+'</span></div>'+(m.description?'<div class="hf-model-desc">'+m.description+'</div>':'')+'<div class="hf-model-tags">'+tags+'</div><div class="hf-model-gguf-info">'+(m.has_gguf?'✓ GGUF':'⚠ 可能无GGUF')+'</div><button class="hf-model-download-btn" data-v="'+m.id+'" '+(m.has_gguf?'':'disabled')+'>查看文件</button></div>';}
c.innerHTML=html;c.querySelectorAll('[data-v]').forEach(function(b){b.addEventListener('click',function(){viewF(b.dataset.v);});});}
async function viewF(mid){_selId=mid;document.getElementById('hfDetailModelId').textContent=mid;document.getElementById('hfDetailBody').innerHTML='<p style="color:var(--text-3);">加载中...</p>';var dp=document.getElementById('hfDetailPanel');dp.removeAttribute('hidden');var sa=document.querySelector('.hf-scroll-area');if(sa)sa.scrollTop=0;try{var f=await window.__TAURI__.core.invoke('get_hf_model_files',{modelId:mid});_files=f;renderF(mid,f);}catch(e){console.error('viewF error:',e);document.getElementById('hfDetailBody').innerHTML='<p style="color:var(--danger);">加载失败: '+e+'</p><p style="color:var(--text-3);font-size:11px;margin-top:8px;">可能是网络问题或模型API超时，请稍后重试</p>';}}
function renderF(mid,files){var b=document.getElementById('hfDetailBody');if(!files||!files.length){b.innerHTML='<p style="color:var(--text-3);">该模型没有 GGUF 文件</p>';return;}
var html='<p style="font-size:12px;color:var(--text-2);margin-bottom:8px;">找到 '+files.length+' 个 GGUF 文件：</p>';
for(var i=0;i<files.length;i++){var f=files[i];var dl='hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+f.path.replace(/[^a-z0-9]/gi,'-');var it=_queue.find(function(d){return d.mid===mid&&d.fn===f.path;});var st=it?it.st:'idle';var pg=it?(it.p||0)*100:0;
var bh=st==='complete'?'<span class="hf-dl-status complete">✓ 完成</span>':st==='downloading'?'<span class="hf-dl-status downloading">'+Math.round(pg)+'%</span>':st==='error'?'<span class="hf-dl-status error">失败</span>':'<button class="hf-model-download-btn" data-d="'+mid+'" data-f="'+f.path+'" data-s="'+f.size+'" style="padding:4px 12px;">下载</button>';
html+='<div class="hf-file-item" id="'+dl+'-item"><div><div class="hf-file-name">'+f.path.split('/').pop()+'</div><div class="hf-file-size">'+fs(f.size)+'</div></div>'+bh+'</div>';}
b.innerHTML=html;b.querySelectorAll('[data-d]').forEach(function(btn){btn.addEventListener('click',function(){startD(btn.dataset.d,btn.dataset.f,parseInt(btn.dataset.s));});});}
async function startD(mid,fn,sz){var dl='hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+fn.replace(/[^a-z0-9]/gi,'-');var it={id:dl,mid:mid,fn:fn,sz:sz||0,st:'downloading',p:0};_queue.push(it);renderDl(it);updateDc();
try{await window.__TAURI__.core.invoke('download_hf_model',{modelId:mid,filename:fn,installDir:null});it.st='complete';it.p=1;renderDl(it);toast('下载完成: '+fn,'success');}catch(e){console.error(e);it.st='error';renderDl(it);toast('下载失败','error');}}
function renderDl(it){var el=document.getElementById(it.id);var st=it.st,pg=Math.round(it.p*100);var html='<div class="hf-dl-info"><span class="hf-dl-status '+st+'">'+(st==='complete'?'✓ 完成':st==='error'?'✕ 失败':st==='downloading'?'↓ '+pg+'%':'等待')+'</span></div><div class="hf-dl-progress-track"><div class="hf-dl-progress-fill" style="width:'+pg+'%"></div></div><div style="flex:1;min-width:0;"><div class="hf-file-name" style="font-size:11px;">'+it.fn.split('/').pop()+'</div><div class="hf-file-size">'+fs(it.sz)+'</div></div>';
if(el){el.innerHTML=html;el.dataset.status=st;}else{var d=document.createElement('div');d.className='hf-download-item';d.id=it.id;d.dataset.status=st;d.innerHTML=html;document.getElementById('hfDownloadsList').appendChild(d);}if(_selId)renderF(_selId,_files);}
function updateDc(){var c=document.getElementById('hfDownloadsCount');if(c)c.textContent=_queue.length;}
function init(){var inStore=!!document.getElementById('hfResultsList');if(inStore){loadS();}var ob=document.getElementById('openHfStoreBtn');if(ob)ob.addEventListener('click',openM);var si=document.getElementById('hfSearchInput');if(si)si.addEventListener('keydown',function(e){if(e.key==='Enter')search(si.value);});var sb=document.getElementById('hfSearchBtn');if(sb)sb.addEventListener('click',function(){search(document.getElementById('hfSearchInput').value);});var ts=document.getElementById('hfTokenSaveBtn');if(ts)ts.addEventListener('click',async function(){var t=document.getElementById('hfTokenInput').value.trim();if(!t){toast('请输入Token','warning');return;}try{await window.__TAURI__.core.invoke('set_hf_token',{token:t});document.getElementById('hfTokenInput').value='********';toast('Token已保存','success');}catch(e){toast('保存失败','error');}});var ds=document.getElementById('hfDownloadDirSaveBtn');if(ds)ds.addEventListener('click',async function(){var d=document.getElementById('hfDownloadDirInput').value.trim();if(!d){toast('请输入目录','warning');return;}try{await window.__TAURI__.core.invoke('set_hf_download_dir',{dir:d});toast('目录已保存','success');}catch(e){toast('保存失败','error');}});window.__TAURI__.event.listen('hf-download-progress',function(ev){var p=ev.payload;var dl='hf-dl-'+p.model_id.replace(/[^a-z0-9]/gi,'-')+'-'+p.filename.replace(/[^a-z0-9]/gi,'-');var it=_queue.find(function(d){return d.id===dl;});if(it){it.st=p.stage==='complete'?'complete':'downloading';it.p=p.stage==='complete'?1:(p.progress||0);renderDl(it);}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
